(()=>{
 let busy=false,touch=null;
 function turn(step){if(busy||location.hash!=='#album'||modal.open)return;const next=diaryIndex+step;if(next<0||next>=C.photos.length)return;const sheet=document.querySelector('.diary-sheet');if(!sheet)return;busy=true;const direction=step>0?'next':'prev';const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;document.querySelectorAll('[data-diary-step]').forEach(b=>b.disabled=true);sheet.className='diary-sheet turn-out-'+direction;setTimeout(()=>{if(location.hash!=='#album'){busy=false;return}diaryIndex=next;sheet.innerHTML=diaryPage();preloadDiaryNext();sheet.className='diary-sheet turn-in-'+direction;document.querySelector('.diary-count').innerHTML=`${diaryIndex+1} / ${C.photos.length}<small>günlüğümüzün sayfaları</small>`;setTimeout(()=>{busy=false;sheet.className='diary-sheet';document.querySelectorAll('[data-diary-step]').forEach(b=>b.disabled=Number(b.dataset.diaryStep)<0?diaryIndex===0:diaryIndex===C.photos.length-1)},reduced?0:300)},reduced?0:200)}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-diary-step]');if(b)turn(Number(b.dataset.diaryStep))});
 document.addEventListener('keydown',e=>{if(location.hash!=='#album'||modal.open||e.ctrlKey||e.metaKey||e.altKey||e.target.matches('input,textarea,select'))return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();turn(e.key==='ArrowRight'?1:-1)}});
 document.addEventListener('touchstart',e=>{if(!e.target.closest('.diary-sheet')||modal.open)return;touch={x:e.touches[0].clientX,y:e.touches[0].clientY}},{passive:true});
 document.addEventListener('touchend',e=>{if(!touch)return;const dx=e.changedTouches[0].clientX-touch.x,dy=e.changedTouches[0].clientY-touch.y;touch=null;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.5)turn(dx<0?1:-1)},{passive:true});
})();
